function validate(input) {
  const [{ Salary = [], Employee = [] }] = input;
  const employees = new Set(), payments = new Set(), monthly = new Set();
  for (const [id, dept] of Employee) {
    if (id === null || dept === null) return 'Every employee needs an employee_id and a department_id.';
    if (employees.has(id)) return `employee_id ${id} appears twice in Employee.`;
    employees.add(id);
  }
  for (const [id, emp, amount, date] of Salary) {
    if (id === null || amount === null) return 'Every payment needs an id and an amount.';
    if (payments.has(id)) return `id ${id} appears twice in Salary.`;
    if (!employees.has(emp)) return `Payment ${id} names unknown employee_id ${emp}.`;
    if (typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return `Payment ${id} needs a pay_date like 2017-03-31.`;
    const key = `${emp}@${date.slice(0, 7)}`;
    if (monthly.has(key)) return `Employee ${emp} is paid twice in ${date.slice(0, 7)}.`;
    payments.add(id); monthly.add(key);
  }
  return null;
}

