function generate(rand, size) {
  const small = size === 'small';
  const months = small ? ['2016-12', '2017-01', '2017-02'] : Array.from({ length: 10 }, (_, i) => `2017-${String(i + 1).padStart(2, '0')}`);
  const days = ['01', '15', '28'];
  const employeeCount = small ? Math.floor(rand() * 6) : 200;
  const deptCount = small ? 3 : 30;
  const Employee = [], Salary = [];
  for (let id = 1; id <= employeeCount; id++) Employee.push([id, 1 + Math.floor(rand() * deptCount)]);
  // Amounts come from a short list so that department and company averages often tie.
  const amounts = [5000, 6000, 7000, 8000, 9000, 10000];
  for (const month of months) {
    for (let id = 1; id <= employeeCount; id++) {
      if (small && (rand() < 0.35 || Salary.length >= 8)) continue;
      Salary.push([Salary.length + 1, id, amounts[Math.floor(rand() * amounts.length)], `${month}-${days[Math.floor(rand() * days.length)]}`]);
    }
  }
  return [{ Salary, Employee }];
}
